insert into public.chapters (chapter, title, scenarios) values (7, 'Structuring and Designing Organizations', '{"Eric the Redd": "Eric Redd graduated from college and was hired by a corporation that manufactured parts for the automotive industry. The employees on the assembly line seemed bored, and their motivation was low. Eric''s employer decided to try to reorganize to increase productivity. During his career, Eric will see his job change from an engineer to a more complex job assignment."}'::jsonb) on conflict (chapter) do update set title = excluded.title, scenarios = excluded.scenarios;
insert into public.questions (id, chapter, num, scenario, question, options, answer, marked, note) values
('c7-q01', 7, 1, null, 'All of the following are part of the process of organizational design EXCEPT ________.', '["deciding how specialized jobs should be", "determining rules for employee behavior", "determining the level at which decisions are made", "determining goals for the organization"]'::jsonb, 'D', 'D', null),
('c7-q02', 7, 2, null, 'Which one of the following pairs include items that are NOT basic elements of organizational design?', '["work specialization, span of control", "chain of command, line authority", "centralization, decentralization", "departmentalization, formalization"]'::jsonb, 'B', 'B', null),
('c7-q03', 7, 3, null, 'Which one of the following is synonymous with work specialization?', '["division of labor", "job discrimination", "chain of command", "job preference"]'::jsonb, 'A', 'A', null),
('c7-q04', 7, 4, null, 'Which statement accurately defines work specialization?', '["It is the degree to which tasks are grouped together.", "Individual employees specialize in doing part of an activity rather than the entire activity.", "Jobs are ranked relative only to their worth or value to the businesses.", "Work specialization clarifies who reports to whom."]'::jsonb, 'B', 'B', null),
('c7-q05', 7, 5, null, 'Early supporters of work specialization saw it as ________.', '["a reliable way to increase productivity", "a good way to increase employee morale", "a source of innovation", "an immoral way to coerce workers into greater productivity"]'::jsonb, 'A', 'A', null),
('c7-q06', 7, 6, null, 'Early users of work specialization in the early twentieth century found that the practice ultimately resulted in ________.', '["higher profits and better employee morale", "bored workers with low morale", "huge and permanent productivity gains", "better communication among employees"]'::jsonb, 'B', 'B', null),
('c7-q07', 7, 7, null, 'Today, managers favor this approach with regard to work specialization.', '["All tasks are performed by all employees to promote fairness.", "Partners switch jobs every half hour to overcome boredom.", "Employees specialize to maintain efficiency.", "Monotonous tasks are shared by all employees to prevent perceived favoritism."]'::jsonb, 'C', 'C', null),
('c7-q08', 7, 8, null, 'Functional departmentalization groups jobs by ________.', '["tasks they perform", "territories they serve", "products or services they manufacture or produce", "type of customer they serve"]'::jsonb, 'A', 'A', null),
('c7-q09', 7, 9, null, 'A soap company that features a bath soap department, a laundry detergent department, and a dish soap department is using which one of the following?', '["process departmentalization", "functional departmentalization", "product departmentalization", "customer departmentalization"]'::jsonb, 'C', 'C', null),
('c7-q10', 7, 10, null, 'What kind of departmentalization would be in place in a government agency in which there are separate departments that provide services for employers, employed workers, unemployed workers, and the disabled?', '["product", "geographic", "outcome", "customer"]'::jsonb, 'D', 'D', null),
('c7-q11', 7, 11, null, 'Health clinic offices usually use this kind of departmentalization.', '["product", "functional", "customer", "process"]'::jsonb, 'D', null, 'Not marked on the sheet. Process departmentalization groups jobs on the basis of product or customer flow – patients move through registration, examination, lab, billing. Somewhat debatable – please double-check with your instructor.'),
('c7-q12', 7, 12, null, 'The chain of command answers this question.', '["Where do I go for help?", "How do I know when the task is complete?", "What are the rules?", "Who reports to whom?"]'::jsonb, 'D', null, 'Not marked on the sheet. Chain of command = line of authority that clarifies who reports to whom.'),
('c7-q13', 7, 13, null, 'In the chain of command, each person above you ________.', '["has special privileges", "receives higher pay", "has line authority", "has no right to give you orders"]'::jsonb, 'C', null, 'Not marked on the sheet. Line authority entitles a manager to direct the work of subordinates.'),
('c7-q14', 7, 14, null, 'Staff managers have authority over ________.', '["support employees only", "line managers", "middle managers", "the person above them in the chain of command"]'::jsonb, 'A', null, 'Not marked on the sheet. Staff authority supports, assists and advises line managers; staff managers only direct their own support staff.'),
('c7-q15', 7, 15, null, 'Line authority gives a manager the ability to direct the work of ________.', '["any employee in the firm", "any subordinate", "any subordinate, after consulting with the next higher level", "only subordinates one level down"]'::jsonb, 'B', null, 'Not marked on the sheet.'),
('c7-q16', 7, 16, null, '________ prevents a single employee from getting conflicting orders from two different superiors.', '["Line authority", "Unity of command", "Staff authority", "Chain of command"]'::jsonb, 'B', null, 'Not marked on the sheet. Unity of command: each person reports to only one manager.'),
('c7-q17', 7, 17, null, 'The importance of unity of command has diminished in today''s workplace because of its tendency to be ________.', '["inflexible and inefficient", "ethically questionable", "chauvinistic and dictatorial", "too decisive"]'::jsonb, 'A', null, 'Not marked on the sheet.'),
('c7-q18', 7, 18, null, 'Which one of the following statements is true?', '["Power is a right.", "Authority is one''s ability to influence decisions.", "Authority is a right.", "Both power and authority are rights."]'::jsonb, 'C', null, 'Not marked on the sheet. Authority is a right (based on position); power is a capacity to influence decisions.'),
('c7-q19', 7, 19, null, 'The personal assistant of a top manager may have ________.', '["power but not authority", "authority but not power", "power and authority", "line authority but not staff authority"]'::jsonb, 'A', null, 'Not marked on the sheet. Being close to the top (power cone) gives influence without formal authority.'),
('c7-q20', 7, 20, null, 'Which one of the following statements is true?', '["Power is a type of authority.", "Authority and power are identical.", "Authority is a type of power.", "Power is determined by horizontal position in an organization."]'::jsonb, 'C', null, 'Not marked on the sheet. Authority is one part of the broader concept of power.'),
('c7-q21', 7, 21, null, 'As represented in a power cone, power is based on ________.', '["vertical position only", "horizontal position only", "distance from the center only", "vertical position and distance from the center"]'::jsonb, 'D', 'D', null),
('c7-q22', 7, 22, null, 'As represented in a hierarchical organization diagram, authority is based on ________.', '["vertical position only", "horizontal position only", "distance from the center only", "horizontal and vertical position"]'::jsonb, 'A', 'A', null),
('c7-q23', 7, 23, null, 'A construction site supervisor who sees an impending thunderstorm and tells workers to go home is demonstrating ________.', '["line authority", "staff delegation", "provisional accountability", "unity of command"]'::jsonb, 'A', 'A', null),
('c7-q24', 7, 24, null, '________ is the power that rests on the leader''s ability to punish or control.', '["Reward power", "Coercive power", "Expert power", "Referent power"]'::jsonb, 'B', 'B', null),
('c7-q25', 7, 25, null, 'A bank manager who passes out bonuses at the end of the year is exercising this.', '["reward power", "coercive power", "expert power", "referent power"]'::jsonb, 'A', 'A', null),
('c7-q26', 7, 26, null, 'Your firm''s attorney has ________ power when giving legal advice.', '["legitimate", "status", "expert", "coercive"]'::jsonb, 'C', 'C', null),
('c7-q27', 7, 27, null, '________ is the power that arises when a person is close to another person who has great power and authority.', '["Expert power", "Referent power", "Reward power", "Legitimate power"]'::jsonb, 'B', 'B', null),
('c7-q28', 7, 28, null, 'When a top manager decides to hire an individual over the objections of her staff, she is exercising which kind of power?', '["referent", "expert", "coercive", "legitimate"]'::jsonb, 'D', 'D', null),
('c7-q29', 7, 29, null, 'Modern managers find that they can ________ if their employees are experienced, well-trained, and motivated.', '["increase their span of control", "decrease their span of control", "eliminate their span of control", "fluctuate their span of control"]'::jsonb, 'A', 'A', null),
('c7-q30', 7, 30, null, 'A ________ subcontracts part of a project to outside suppliers.', '["virtual organization", "boundary organization", "matrix structure", "network organization"]'::jsonb, 'D', 'D', null),
('c7-q31', 7, 31, null, 'A building contractor follows the network organization model when he does which one of the following?', '["does the framing and tiling by himself", "hires three workers to help with framing", "gives orders to workers", "farms out the plumbing to a plumbing firm"]'::jsonb, 'D', 'D', null),
('c7-q32', 7, 32, 'Eric the Redd', 'Eric, who is trained as an engineer, is now in a group with production workers and marketing specialists from different departments designing a new product that the company plans to offer. This situation could be described as a(n) ________.', '["alternative assignment", "collective assignment", "advanced assignment", "project assignment"]'::jsonb, 'D', 'D', null),
('c7-q33', 7, 33, null, 'Which one of the following is the biggest concern when doing work at anytime and anywhere?', '["employee payroll", "security", "employee accountability", "customer satisfaction"]'::jsonb, 'B', 'C', 'CORRECTED: C is circled on the sheet. The textbook names security (protecting the company''s important and sensitive information) as the biggest concern of anytime/anywhere work. Please double-check with your instructor.'),
('c7-q34', 7, 34, null, 'Global competition forces firms to ________.', '["become lean, fast, and flexible", "build up enormous cash reserves", "think locally", "become more hierarchical"]'::jsonb, 'A', 'A', null),
('c7-q35', 7, 35, null, 'A learning organization develops the capability to ________.', '["add new training programs to keep employees up to date", "accept the conventional wisdom of the industry", "continuously learn, adapt, and change", "attract new employees who have special knowledge"]'::jsonb, 'C', 'C', null),
('c7-q36', 7, 36, null, 'A learning organization requires employees to ________.', '["encode information to prevent competitors from stealing ideas", "collaborate with competitors", "make all ideas public", "share information and collaborate with one another"]'::jsonb, 'D', 'D', null),
('c7-q37', 7, 37, null, 'All of the following are characteristic of learning organizations EXCEPT ________.', '["a strong sense of community", "a collaborative environment", "managers who serve as facilitators", "fear of making mistakes"]'::jsonb, 'D', 'D', null),
('c7-q38', 7, 38, null, 'Organizational learning can''t take place without ________.', '["complete privacy for employees", "a clear chain of command", "information", "a stable structure or hierarchy"]'::jsonb, 'C', 'C', null),
('c7-q39', 7, 39, null, 'In a learning organization, it is important that all employees ________.', '["collaborate", "study each night", "have a strong sense of leadership", "share the same vision for the organization"]'::jsonb, 'D', null, 'Not marked on the sheet. Learning organizations need a shared vision that everyone agrees on ("collaborate" is also a feature, but the textbook stresses the shared vision for ALL employees). Debatable – please double-check with your instructor.'),
('c7-q40', 7, 40, null, 'Organizational design requires a manager to ________.', '["decide who leads a group within an organization", "change the culture of an organization", "change or develop the structure of an organization", "change the logo of an organization"]'::jsonb, 'C', 'C', null)
insert into public.open_questions (id, chapter, num, question, model_answer) values
('c7-o1', 7, 1, 'In a short essay, describe the matrix structure. What are its advantages and disadvantages?', 'A matrix structure assigns specialists from different functional departments to work on one or more projects led by a project manager. It creates a dual chain of command: employees report both to their functional manager and to the project manager, so it violates the unity-of-command principle. When a project is finished, specialists return to their functional departments.
